private static Release latest(boolean prerelease) throws Exception {
    JSONObject wrapper;
    try {
        wrapper = getJson(API + "/releases?per_page=100");
    } catch (Exception e) {
        // Unauthenticated API calls are limited to 60/hour per IP (shared VPN exits run out), the Atom feed is not.
        FileLog.e("GitHubUpdater: API failed, using the releases feed", e);
        return latestFromFeed();
    }
    JSONArray releases = wrapper == null ? null : wrapper.optJSONArray("items");
    if (releases == null) {
        return null;
    }
    // GitHub lists releases by tag name, and "ci-<sha>" tags are not chronological: pick the newest by date.
    String ownTag = ownTag();
    long own = 0;
    Release best = null;
    Release bestPre = null;
    for (int i = 0; i < releases.length(); i++) {
        JSONObject item = releases.optJSONObject(i);
        if (item == null || item.optBoolean("draft")) {
            continue;
        }
        String tag = item.optString("tag_name");
        long published = parseDate(item.optString("published_at"));
        if (tag.equals(ownTag)) {
            own = published;
        }
        JSONObject asset = pickAsset(item.optJSONArray("assets"));
        if (asset == null) {
            continue;
        }
        boolean pre = item.optBoolean("prerelease");
        Release current = pre ? bestPre : best;
        if (current != null && current.published >= published) {
            continue;
        }
        Release release = new Release();
        release.tag = tag;
        release.name = item.optString("name", release.tag);
        release.body = item.optString("body", "");
        release.apkUrl = asset.optString("browser_download_url");
        release.apkName = asset.optString("name");
        release.apkSize = asset.optLong("size");
        release.published = published;
        if (pre) {
            bestPre = release;
        } else {
            best = release;
        }
    }
    // CI publishes prereleases only, so the release channel falls back to them while there is no full release.
    Release result = best == null || prerelease && bestPre != null && bestPre.published > best.published ? bestPre : best;
    if (result != null) {
        result.currentPublished = own;
    }
    return result;
}

private static Release latestFromFeed() throws Exception {
    Request request = new Request.Builder().url(RELEASES_URL + ".atom")
            .header("User-Agent", "TsundereGram")
            .build();
    String xml;
    try (Response response = client().newCall(request).execute()) {
        ResponseBody body = response.body();
        if (!response.isSuccessful() || body == null) {
            throw new IllegalStateException("HTTP " + response.code());
        }
        xml = body.string();
    }
    String ownTag = ownTag();
    long own = 0;
    Release best = null;
    Matcher entry = FEED_ENTRY.matcher(xml);
    while (entry.find()) {
        String text = entry.group(1);
        String tag = find(FEED_TAG, text);
        if (tag == null) {
            continue;
        }
        long published = parseDate(find(FEED_UPDATED, text));
        if (tag.equals(ownTag)) {
            own = published;
        }
        if (best != null && best.published >= published) {
            continue;
        }
        // the feed has no asset list: CI always uploads the APK under the same name
        Release release = new Release();
        release.tag = tag;
        String title = find(FEED_TITLE, text);
        release.name = TextUtils.isEmpty(title) ? tag : title;
        release.body = "";
        release.apkName = FEED_APK;
        release.apkUrl = RELEASES_URL + "/download/" + tag + "/" + FEED_APK;
        release.published = published;
        best = release;
    }
    if (best != null) {
        best.currentPublished = own;
    }
    return best;
}

private static String find(Pattern pattern, String text) {
    Matcher matcher = pattern.matcher(text);
    return matcher.find() ? matcher.group(1) : null;
}

private static String ownTag() {
    String commit = BuildConfig.BUILD_COMMIT_ID;
    return TextUtils.isEmpty(commit) ? null : "ci-" + commit;
}

