private static Boolean isNewer(Release release) {
    Integer versionOrder = compareVersion(release);
    if (versionOrder != null && versionOrder != 0) {
        return versionOrder > 0;
    }
    // All CI builds share one version name; tell them apart by this build's own "ci-<commit>" release.
    String own = ownTag();
    if (own != null) {
        if (own.equals(release.tag)) {
            return false;
        }
        if (release.currentPublished > 0) {
            return release.published > release.currentPublished;
        }
    }
    if (BuildConfig.BUILD_TIMESTAMP > 0 && release.published > 0) {
        return release.published > BuildConfig.BUILD_TIMESTAMP * 1000L;
    }
    if (own != null) {
        return true;
    }
    return versionOrder != null ? Boolean.FALSE : null;
}

// "Theme" colors: the card and its content use the active theme's tab bar and text colors instead of a
// tonal palette built from the accent, which stayed blue on any theme with the default blue accent.
public static PlayerColors fromTheme(Theme.ResourcesProvider resourcesProvider) {
    boolean dark = isDark(resourcesProvider);
    int[] c = fromSeed(fallbackSeed(resourcesProvider), dark).values();
    int background = Theme.getColor(Theme.key_windowBackgroundWhite, resourcesProvider) | 0xff000000;
    int card = ColorUtils.compositeColors(Theme.getColor(Theme.key_glass_targetMainTabs, resourcesProvider), background);
    c[10] = Theme.getColor(Theme.key_windowBackgroundWhiteBlackText, resourcesProvider) | 0xff000000;
    // AMOLED themes paint the tab bar like the background: lift the card so it stays visible
    c[9] = card == background ? ColorUtils.blendARGB(background, c[10], 0.08f) : card;
    return new PlayerColors(dark, c);
}

