    private MessageObject fallbackLinksMessage;
    private Spanned fallbackLinksText;

    // TsundereGram: запасной поиск ссылок для сообщений, где штатный разбор ничего не нашёл
    // (ссылка внутри pre/code, ссылка без сущности url, превью-заглушка webPageEmpty/Pending).
    private void gatherFallbackLinks() {
        if (message == null || message.messageOwner == null) {
            return;
        }
        final TLRPC.MessageMedia media = message.messageOwner.media;
        if (media != null && media.webpage != null && !TextUtils.isEmpty(media.webpage.url)) {
            gatherLink(media.webpage.url);
        }
        if (links.isEmpty() && message.messageText instanceof Spanned) {
            addFallbackUrlSpans((Spanned) message.messageText);
        }
        if (links.isEmpty() && !TextUtils.isEmpty(message.messageOwner.message)) {
            if (fallbackLinksMessage != message) {
                fallbackLinksMessage = message;
                fallbackLinksText = null;
                final SpannableString text = new SpannableString(message.messageOwner.message);
                if (AndroidUtilities.addLinksSafe(text, Linkify.WEB_URLS, false, false)) {
                    fallbackLinksText = text;
                }
            }
            if (fallbackLinksText != null) {
                addFallbackUrlSpans(fallbackLinksText);
            }
        }
    }

    private void addFallbackUrlSpans(final Spanned text) {
        final URLSpan[] spans = text.getSpans(0, text.length(), URLSpan.class);
        if (spans == null || spans.length == 0) {
            return;
        }
        java.util.Arrays.sort(spans, (a, b) -> Integer.compare(text.getSpanStart(a), text.getSpanStart(b)));
        for (int i = 0; i < spans.length; i++) {
            final String raw = spans[i].getURL();
            if (raw == null) {
                continue;
            }
            final String url = raw.trim();
            if (url.isEmpty() || url.startsWith("@") || url.startsWith("#") || url.startsWith("/") || url.startsWith("$")
                    || url.startsWith("tel:") || url.startsWith("video?") || url.startsWith("audio?")) {
                continue;
            }
            if (!url.contains("://") && !url.startsWith("mailto:") && !url.contains(".")) {
                continue;
            }
            boolean duplicate = false;
            for (int j = 0; j < links.size(); j++) {
                final String existing = links.get(j).toString();
                if (existing.equals(url) || existing.equals("http://" + url)) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) {
                gatherLink(url);
            }
        }
    }

    private static String titleFromLink(String link) {
        if (link == null) {
            return null;
        }
        if (link.startsWith("mailto:")) {
            return link.substring(7);
        }
        String title = link;
        try {
            final String host = Uri.parse(link).getHost();
            if (host != null) {
                title = host;
            }
            int index;
            if ((index = title.lastIndexOf('.')) > 0) {
                title = title.substring(0, index);
                if ((index = title.lastIndexOf('.')) >= 0) {
                    title = title.substring(index + 1);
                }
                if (title.length() > 0) {
                    title = title.substring(0, 1).toUpperCase() + title.substring(1);
                }
            }
        } catch (Exception e) {
            FileLog.e(e);
        }
        return TextUtils.isEmpty(title) ? link : title;
    }

