private static String formatCount(int n, String one, String few, String many) {
    int m10 = n % 10, m100 = n % 100;
    String w = m10 == 1 && m100 != 11 ? one : m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14) ? few : many;
    return String.format(Locale.US, "%,d", n).replace(',', ' ') + " " + w;

